pub struct Customer {
    pub years_with_mhpco: i64,
}

pub struct Item {
    pub item_type: String,
}

const PROCESSING_FEE: i64 = 5;

const FIRST_INSURANCE_SURCHARGE: f64 = 0.10;

const SWORD_BASE_PREMIUM: f64 = 100.0;
const AMULET_BASE_PREMIUM: f64 = 60.0;
const STAFF_BASE_PREMIUM: f64 = 80.0;
const POTION_BASE_PREMIUM: f64 = 40.0;
const COMPONENT_BASE_PREMIUM: f64 = 25.0;
const COMPONENT_BLOCK_SIZE: usize = 3;
const COMPONENT_BLOCK_BASE_PREMIUM: f64 = 60.0;

/// Components are the small insurable parts the MHPCO lists apart from main
/// items: they are priced per component and may form building blocks.
fn is_component(item: &Item) -> bool {
    matches!(item.item_type.as_str(), "rune" | "moonstone")
}

/// The MHPCO price list: the base premium each insurable item type carries.
fn base_premium(item: &Item) -> f64 {
    if is_component(item) {
        return COMPONENT_BASE_PREMIUM;
    }
    match item.item_type.as_str() {
        "amulet" => AMULET_BASE_PREMIUM,
        "staff" => STAFF_BASE_PREMIUM,
        "potion" => POTION_BASE_PREMIUM,
        _ => SWORD_BASE_PREMIUM,
    }
}

/// A building block of alike components is offered at a special base premium.
fn component_group_base_premium(count: usize) -> f64 {
    if count == COMPONENT_BLOCK_SIZE {
        COMPONENT_BLOCK_BASE_PREMIUM
    } else {
        count as f64 * COMPONENT_BASE_PREMIUM
    }
}

/// The policy base premium: the sum of the base premiums of all insured items,
/// with alike components priced together so their building block can apply.
fn policy_base_premium(items: &[Item]) -> f64 {
    let main_items: f64 = items
        .iter()
        .filter(|item| !is_component(item))
        .map(base_premium)
        .sum();
    let mut components: Vec<&str> = items
        .iter()
        .filter(|item| is_component(item))
        .map(|item| item.item_type.as_str())
        .collect();
    components.sort_unstable();
    let mut blocks = 0.0;
    let mut rest = &components[..];
    while let Some(first) = rest.first() {
        let count = rest.iter().take_while(|kind| *kind == first).count();
        blocks += component_group_base_premium(count);
        rest = &rest[count..];
    }
    main_items + blocks
}

/// Policy-wide modifiers, applied to the policy base premium.
fn apply_policy_modifiers(base: f64, _customer: &Customer, _previous_quotes: usize) -> f64 {
    base + base * FIRST_INSURANCE_SURCHARGE
}

/// Amounts are rounded in the MHPCO's favor: a premium is rounded up.
fn round_in_mhpco_favor(premium: f64) -> i64 {
    premium.ceil() as i64
}

pub fn quote(customer: &Customer, items: &[Item], previous_quotes: usize) -> i64 {
    let base = policy_base_premium(items);
    let premium = apply_policy_modifiers(base, customer, previous_quotes);
    round_in_mhpco_favor(premium) + PROCESSING_FEE
}

