mod tests {
    use super::*;

    #[test]
    fn empty_item_list_costs_only_the_processing_fee() {
        let customer = Customer { years_with_mhpco: 0 };
        assert_eq!(quote(&customer, &[], 0), 5);
    }

    #[test]
    fn plain_sword_uses_its_base_premium() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [Item { item_type: "sword".to_string() }];
        assert_eq!(quote(&customer, &items, 0), 115);
    }

    #[test]
    fn plain_amulet_uses_its_base_premium() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [Item { item_type: "amulet".to_string() }];
        assert_eq!(quote(&customer, &items, 0), 71);
    }

    #[test]
    fn plain_staff_uses_its_base_premium() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [Item { item_type: "staff".to_string() }];
        assert_eq!(quote(&customer, &items, 0), 93);
    }

    #[test]
    fn plain_potion_uses_its_base_premium() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [Item { item_type: "potion".to_string() }];
        assert_eq!(quote(&customer, &items, 0), 49);
    }

    #[test]
    fn single_rune_uses_the_component_base_premium() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [Item { item_type: "rune".to_string() }];
        assert_eq!(quote(&customer, &items, 0), 33);
    }

    #[test]
    fn single_moonstone_uses_the_component_base_premium() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [Item { item_type: "moonstone".to_string() }];
        assert_eq!(quote(&customer, &items, 0), 33);
    }

    #[test]
    fn two_runes_cost_fifty() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [
            Item { item_type: "rune".to_string() },
            Item { item_type: "rune".to_string() },
        ];
        assert_eq!(quote(&customer, &items, 0), 60);
    }

    #[test]
    fn three_runes_form_a_block() {
        let customer = Customer { years_with_mhpco: 0 };
        let items = [
            Item { item_type: "rune".to_string() },
            Item { item_type: "rune".to_string() },
            Item { item_type: "rune".to_string() },
        ];
        assert_eq!(quote(&customer, &items, 0), 71);
    }

    #[test]
    #[ignore = "TODO: 4 runes -> 100 G base premium (block requires exactly 3)"]
    fn four_runes_do_not_form_a_block() {}

    #[test]
    #[ignore = "TODO: 7 runes -> 175 G base premium"]
    fn seven_runes_do_not_form_a_block() {}

    #[test]
    #[ignore = "TODO: 2 runes + 1 moonstone -> 75 G (alike means same type)"]
    fn mixed_component_types_do_not_form_a_block() {}

    #[test]
    #[ignore = "TODO: 3 runes + 3 moonstones -> 120 G (two separate blocks)"]
    fn two_separate_component_types_each_form_a_block() {}

    #[test]
    #[ignore = "TODO: cursed sword adds 50% of the item's base premium"]
    fn cursed_item_adds_a_fifty_percent_surcharge() {}

    #[test]
    #[ignore = "TODO: sword with enchantment 5 adds 30% high-enchantment surcharge"]
    fn enchantment_of_exactly_five_adds_the_high_enchantment_surcharge() {}

    #[test]
    #[ignore = "TODO: sword with enchantment 4 adds no high-enchantment surcharge"]
    fn enchantment_of_four_adds_no_high_enchantment_surcharge() {}

    #[test]
    #[ignore = "TODO: cursed sword with enchantment 5 adds both surcharges"]
    fn cursed_and_highly_enchanted_item_adds_both_surcharges() {}

    #[test]
    #[ignore = "TODO: customer with exactly 2 years gets the 20% loyalty discount"]
    fn exactly_two_years_grants_the_loyalty_discount() {}

    #[test]
    #[ignore = "TODO: customer with 1 year gets no loyalty discount"]
    fn one_year_grants_no_loyalty_discount() {}

    #[test]
    #[ignore = "TODO: first quote in a scenario carries the 10% initial assessment surcharge"]
    fn first_insurance_adds_the_initial_assessment_surcharge() {}

    #[test]
    #[ignore = "TODO: the second quote in a scenario receives the 15% follow-up contract discount"]
    fn follow_up_contract_grants_the_fifteen_percent_discount() {}

    #[test]
    #[ignore = "TODO: first insurance surcharge still applies on a follow-up contract"]
    fn first_insurance_surcharge_applies_on_every_quote() {}

    #[test]
    #[ignore = "TODO: cursed sword + plain amulet -> base 160 G, curse adds 50 G -> 210 G before policy modifiers and fee"]
    fn item_modifiers_apply_only_to_the_affected_items_base_premium() {}

    #[test]
    #[ignore = "TODO: premium yielding 197.5 G -> 198 G (rounded up in MHPCO's favor)"]
    fn premium_is_rounded_up() {}

    #[test]
    #[ignore = "TODO: newcomer with a cursed sword -> premium 165 G"]
    fn newcomer_with_a_cursed_sword_pays_165() {}

    #[test]
    #[ignore = "TODO: long-standing customer's second contract, cursed sword enchantment 7 -> premium 160 G"]
    fn long_standing_customers_second_contract_pays_160() {}

    #[test]
    #[ignore = "TODO: quote with an unknown item type -> non-zero exit, error on stderr, no results on stdout"]
    fn quote_with_an_unknown_item_type_is_rejected() {}

    #[test]
    #[ignore = "TODO: regular sword (steel, enchantment 3), damage 500 G -> payout 400 G"]
    fn standard_damage_is_reimbursed_minus_the_deductible() {}

    #[test]
    #[ignore = "TODO: rune damage 200 G -> payout 100 G (no enchantment or material)"]
    fn component_damage_is_reimbursed_minus_the_deductible() {}

    #[test]
    #[ignore = "TODO: steel sword enchantment 9, damage 1000 G -> payout 400 G (50% then deductible)"]
    fn highly_enchanted_damage_is_reimbursed_at_half() {}

    #[test]
    #[ignore = "TODO: dragon-material sword enchantment 5, damage 800 G -> payout 700 G"]
    fn dragon_material_damage_is_fully_reimbursed() {}

    #[test]
    #[ignore = "TODO: dragon sword enchantment 8, damage 1000 G -> payout 400 G (threshold is >= 8)"]
    fn enchantment_of_exactly_eight_triggers_the_half_reimbursement() {}

    #[test]
    #[ignore = "TODO: dragon sword enchantment 9, damage 1000 G -> payout 400 G (50% rule wins)"]
    fn high_enchantment_beats_dragon_material() {}

    #[test]
    #[ignore = "TODO: sword 500 G and amulet 300 G in one incident -> payout 600 G (deductible per damaged item)"]
    fn the_deductible_applies_once_per_damaged_item() {}

    #[test]
    #[ignore = "TODO: payout yielding 350.5 G -> 350 G (rounded down in MHPCO's favor)"]
    fn payout_is_rounded_down() {}

    #[test]
    #[ignore = "TODO: policy with a sword and an amulet -> insurance sum 1600 G, cap 3200 G"]
    fn the_cap_is_twice_the_sum_of_the_items_insurance_values() {}

    #[test]
    #[ignore = "TODO: cursed sword -> cap 2000 G; premium modifiers do not raise the cap"]
    fn premium_modifiers_do_not_raise_the_cap() {}

    #[test]
    #[ignore = "TODO: sword + 3 runes -> insurance sum 1750 G; the block discount affects the premium only"]
    fn the_component_block_discount_does_not_lower_the_insurance_sum() {}

    #[test]
    #[ignore = "TODO: sword, two claims of 1500 G -> payout 1400 G (cap 600 left), then payout 600 G (cap 0)"]
    fn successive_claims_exhaust_the_remaining_cap() {}

    #[test]
    #[ignore = "TODO: policy with two swords -> insurance sum 2000 G, cap 4000 G"]
    fn two_items_of_the_same_type_are_insured_separately() {}

    #[test]
    #[ignore = "TODO: two sword damages against two insured swords -> each has its own deductible"]
    fn each_damage_entry_of_the_same_type_carries_its_own_deductible() {}

    #[test]
    #[ignore = "TODO: more damage entries of a type than insured items -> non-zero exit, whole claim rejected"]
    fn more_damages_of_a_type_than_insured_items_is_rejected() {}

    #[test]
    #[ignore = "TODO: claim for an item not in the policy -> non-zero exit, error on stderr"]
    fn claim_for_an_uninsured_item_is_rejected() {}

    #[test]
    #[ignore = "TODO: claim damage with an unknown item type -> non-zero exit, error on stderr"]
    fn claim_with_an_unknown_item_type_is_rejected() {}

    #[test]
    #[ignore = "TODO: claim damage with amount -200 -> non-zero exit, error on stderr"]
    fn claim_with_a_negative_damage_amount_is_rejected() {}

    #[test]
    #[ignore = "TODO: schema example scenario -> results array with a quote premium and a claim payout/remainingCap"]
    fn a_scenario_produces_one_result_per_step_in_order() {}
}

